-- ==============================================================================\n-- TESTING AND VALIDATION\n-- ==============================================================================\n-- Test statements are kept separate from deployment SQL.\n-- Use test IDs so genuine project records are not modified.\n\nUSE DATABASE MARKETING_CAMP_ANALYSIS;\nUSE SCHEMA RAW_DATA;\n\n-- CUSTOMER JOURNEY\n-- INSERT INTO RAW_DATA.CUSTOMER_JOURNEY\n-- (JOURNEYID, CUSTOMERID, PRODUCTID, VISITDATE, STAGE, ACTION, DURATION)\n-- VALUES (3934, 64, 18, '2026-09-11', 'Checkout', 'Test-Insert', '100');\nSELECT * FROM RAW_DATA.CUSTOMER_JOURNEY_STREAM;\nSELECT COUNT(*) FROM CLEAN_DATA.CUSTOMER_JOURNEY;\nSELECT MAX(JOURNEYID) AS MAX_JOURNEYID FROM CLEAN_DATA.CUSTOMER_JOURNEY;\n-- EXECUTE TASK CLEAN_DATA.CUSTOMER_JOURNEY_TASK;\n\n-- CUSTOMERS\n-- INSERT INTO RAW_DATA.CUSTOMERS\n-- (CUSTOMER_ID, CUSTOMER_NAME, EMAIL, GENDER, AGE, GEOGRAPHY_ID)\n-- VALUES (9999, 'Test Customer', 'test9999@example.com', 'Male', 30, 2);\nSELECT * FROM RAW_DATA.CUSTOMERS_STREAM;\nSELECT * FROM RAW_DATA.CUSTOMERS WHERE CUSTOMER_ID = 9999;\nSELECT * FROM CLEAN_DATA.CUSTOMERS WHERE CUSTOMER_ID = 9999;\n-- EXECUTE TASK CLEAN_DATA.CUSTOMERS_TASK;\n\n-- GEOGRAPHY\n-- INSERT INTO RAW_DATA.GEOGRAPHY\n-- (GEOGRAPHY_ID, COUNTRY, CITY)\n-- VALUES (9999, 'INDIA', 'MUMBAI');\nSELECT * FROM RAW_DATA.GEOGRAPHY_STREAM;\nSELECT * FROM CLEAN_DATA.GEOGRAPHY WHERE GEOGRAPHY_ID = 9999;\n-- EXECUTE TASK CLEAN_DATA.GEOGRAPHY_TASK;\n\n-- PRODUCTS\n-- INSERT INTO RAW_DATA.PRODUCTS(PRODUCT_ID, PRODUCT_NAME, CATEGORY, PRICE)\n-- VALUES(99, 'Cricket Bat', 'Cricket', 899);\nSELECT * FROM RAW_DATA.PRODUCTS_STREAM;\nSELECT * FROM RAW_DATA.PRODUCTS;\nSELECT * FROM CLEAN_DATA.PRODUCTS WHERE PRODUCT_ID = 99;\n-- EXECUTE TASK CLEAN_DATA.PRODUCTS_TASK;\n\n-- ENGAGEMENT\n-- INSERT INTO RAW_DATA.CUSTOMERS_ENGAGEMENT\n-- VALUES(9999, 48, 'video', 260, '2023-05-23', 17, 8, '1000-450');\nSELECT * FROM RAW_DATA.CUSTOMER_ENGAGEMENT_STREAM;\nSELECT * FROM CLEAN_DATA.CUSTOMERS_ENGAGEMENT WHERE ENGAGEMENT_ID = 9999;\n-- EXECUTE TASK CLEAN_DATA.ENGAGEMENT_TASK;\n\n-- TASK HISTORY\nSELECT NAME, STATE, SCHEDULED_TIME, COMPLETED_TIME, ERROR_CODE, ERROR_MESSAGE\nFROM TABLE(INFORMATION_SCHEMA.TASK_HISTORY())\nWHERE SCHEMA_NAME = 'CLEAN_DATA'\nORDER BY SCHEDULED_TIME DESC\nLIMIT 20;\n